    onReady: () => {
      readyCount += 1
      melonReady = true
    }
  }
  game._markSceneDebugDirty = () => {}
  game._scheduleViewportCommit = () => {}
  scene.onReady(() => game._publishReadyIfSceneBuilt(mountToken))
