scene._v2AgentAdapter = { lookup: id => ({
  stableId: id === 'a' ? 'z-adapter-id' : 'a-adapter-id',
  floorId: 'floor-1', elevation: 0
}) }
expect(scene._worldUiEntries().map(entry => entry.stableId)).to.deep.equal(v1)

