  overlay.draw({
    getContext: () => ({
      save: () => {}, restore: () => {}, beginPath: () => {}, moveTo: () => {}, lineTo: () => {},
      closePath: () => {}, rect: () => {}, fill: () => {}, stroke: () => {},
      fillText: text => feedback.push(text),
